#include "SentryClient.hpp"

#include "slic3r/GUI/JusPrin/Support/ErrorReport.hpp"
#include "slic3r/GUI/JusPrin/Support/SentryEvent.hpp"
#include "slic3r/GUI/JusPrin/Support/ThrowStack.hpp"
#include "slic3r/GUI/JusPrin/Updates/Version.hpp"
#include "slic3r/Utils/Http.hpp"
#include "libslic3r/Utils.hpp"

#include <boost/dll/runtime_symbol_info.hpp>
#include <boost/log/trivial.hpp>

#include <sentry.h>

#include <chrono>
#include <condition_variable>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <filesystem>
#include <mutex>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin {

namespace {

// The Sentry project reports go to. A release build gets it from the release
// workflow (JusPrin/sources.cmake), so the repository names no production
// host; JUSPRIN_SENTRY_DSN in the environment takes its place, which is how a
// test points the app at a stand-in. A build with neither sends no report.
#ifndef JUSPRIN_SENTRY_DSN
#define JUSPRIN_SENTRY_DSN ""
#endif
std::string sentry_dsn()
{
    if (const char* chosen = std::getenv("JUSPRIN_SENTRY_DSN"); chosen != nullptr && *chosen != '\0')
        return chosen;
    return JUSPRIN_SENTRY_DSN;
}

bool g_started = false;
// Who reports and crashes name: the account signed in, or else the install.
std::string g_install_id;
std::string g_account_id;

// The SDK hands each envelope to OrcaSlicer's own HTTP client, which knows
// the system's certificates and proxy on every platform; the SDK's own curl
// transport would need both set up a second time. Anonymous: no token or
// cookie goes with it.
struct Uploads
{
    SentryDsn               dsn;
    std::mutex              mutex;
    std::condition_variable idle;
    int                     pending = 0;
};

void upload_done(Uploads& uploads)
{
    std::lock_guard<std::mutex> lock(uploads.mutex);
    --uploads.pending;
    uploads.idle.notify_all();
}

void send_envelope(sentry_envelope_t* envelope, void* state)
{
    Uploads&    uploads = *static_cast<Uploads*>(state);
    std::size_t size    = 0;
    char*       body    = sentry_envelope_serialize(envelope, &size);
    sentry_envelope_free(envelope);
    std::string payload(body, size);
    sentry_free(body);
    {
        std::lock_guard<std::mutex> lock(uploads.mutex);
        ++uploads.pending;
    }
    Slic3r::Http::post(uploads.dsn.envelope_url)
        .header("User-Agent", Updates::user_agent())
        .header("Content-Type", "application/x-sentry-envelope")
        .header("X-Sentry-Auth", sentry_auth_header(uploads.dsn, std::string("jusprin.app/") + Updates::kVersion))
        .set_post_body(payload)
        .tls_verify(true)
        .timeout_connect(10)
        .timeout_max(30)
        .on_complete([&uploads](std::string, unsigned) { upload_done(uploads); })
        .on_error([&uploads](std::string body, std::string error, unsigned status) {
            BOOST_LOG_TRIVIAL(error) << "JusPrin could not send an error report to " << uploads.dsn.envelope_url << " (" << status
                                     << "): " << error << " " << body;
            upload_done(uploads);
        })
        .perform();
}

// Waits for the uploads under way, at most `timeout` milliseconds; 0 when
// none is left.
int wait_for_uploads(uint64_t timeout, void* state)
{
    Uploads&                     uploads = *static_cast<Uploads*>(state);
    std::unique_lock<std::mutex> lock(uploads.mutex);
    return uploads.idle.wait_for(lock, std::chrono::milliseconds(timeout), [&uploads] { return uploads.pending == 0; }) ? 0 : 1;
}

// This run's log file (GUI_App's set_log_path_and_level names it after the
// process id); none when the system writes no log file.
std::optional<std::filesystem::path> log_file(const std::string& data_dir)
{
    const std::filesystem::path folder = std::filesystem::u8path(data_dir) / "log";
    if (!std::filesystem::is_directory(folder))
        return std::nullopt;
    const std::string ending = "_" + std::to_string(get_current_pid()) + ".log.0";
    for (const std::filesystem::directory_entry& entry : std::filesystem::directory_iterator(folder)) {
        const std::string name = entry.path().filename().string();
        if (name.size() > ending.size() && name.compare(name.size() - ending.size(), ending.size(), ending) == 0)
            return entry.path();
    }
    return std::nullopt;
}

// The person is the signed-in account, or else this install. The install
// is a tag as well, so one person's reports from before and after signing in
// can be matched, and matched to the server's record of the install's starts.
void name_person()
{
    if (!g_install_id.empty())
        sentry_set_tag("install_id", g_install_id.c_str());
    const std::string& id = g_account_id.empty() ? g_install_id : g_account_id;
    if (id.empty()) {
        sentry_remove_user();
        return;
    }
    sentry_value_t user = sentry_value_new_object();
    sentry_value_set_by_key(user, "id", sentry_value_new_string(id.c_str()));
    sentry_set_user(user);
}

} // namespace

void start_sentry(const std::string& data_dir, bool reports_automatically, const std::string& install_id)
{
    if (g_started)
        return;
    const std::optional<SentryDsn> dsn = parse_sentry_dsn(sentry_dsn());
    if (!dsn) {
        BOOST_LOG_TRIVIAL(warning) << "JusPrin sends no error reports or crashes: this build has no Sentry project to send them to";
        return;
    }
    // Lives as long as the app: the SDK may send until the process ends.
    auto* uploads = new Uploads{*dsn};
    sentry_transport_t* transport = sentry_transport_new(send_envelope);
    sentry_transport_set_state(transport, uploads);
    sentry_transport_set_flush_func(transport, wait_for_uploads);
    sentry_transport_set_shutdown_func(transport, wait_for_uploads);

    // crashpad_handler ships beside the app's executable
    // (JusPrin/CMakeLists.txt).
    const std::filesystem::path handler = std::filesystem::path(boost::dll::program_location().native()).parent_path() /
#ifdef _WIN32
                                          "crashpad_handler.exe";
#else
                                          "crashpad_handler";
#endif
    const std::filesystem::path database = std::filesystem::u8path(data_dir) / "jusprin-sentry";

    sentry_options_t* options = sentry_options_new();
    sentry_options_set_dsn(options, sentry_dsn().c_str());
    sentry_options_set_release(options, Updates::version_label().c_str());
    sentry_options_set_transport(options, transport);
    sentry_options_set_require_user_consent(options, 1);
#ifdef _WIN32
    sentry_options_set_handler_pathw(options, handler.wstring().c_str());
    sentry_options_set_database_pathw(options, database.wstring().c_str());
#else
    sentry_options_set_handler_path(options, handler.string().c_str());
    sentry_options_set_database_path(options, database.string().c_str());
#endif
    // Every report and crash carries this run's log.
    if (const std::optional<std::filesystem::path> log = log_file(data_dir)) {
#ifdef _WIN32
        sentry_options_add_attachmentw(options, log->wstring().c_str());
#else
        sentry_options_add_attachment(options, log->string().c_str());
#endif
    }
    if (sentry_init(options) != 0) {
        BOOST_LOG_TRIVIAL(error) << "JusPrin could not start Sentry's SDK; it sends no error reports or crashes";
        return;
    }
    g_started = true;
    g_install_id = install_id;
    name_person();
    start_recording_throws();
    sentry_follow_setting(reports_automatically);
}

void stop_sentry()
{
    if (!g_started)
        return;
    g_started = false;
    sentry_close();
}

void sentry_follow_setting(bool reports_automatically)
{
    if (!g_started)
        return;
    if (reports_automatically)
        sentry_user_consent_give();
    else
        sentry_user_consent_revoke();
}

void sentry_send(const ErrorReport& report, bool reports_automatically)
{
    if (!g_started) {
        BOOST_LOG_TRIVIAL(error) << "JusPrin could not send an error report: Sentry's SDK is not running";
        return;
    }
    sentry_value_t event = sentry_event(report);
    // Where the app found the failure: where it was thrown, or the code that
    // reported it; a page's event has the page's own stack.
    if (report.page_event.empty()) {
        std::vector<void*> frames = report.stack;
        sentry_event_value_add_stacktrace(event, frames.empty() ? nullptr : frames.data(), frames.size());
    }
    if (reports_automatically) {
        sentry_capture_event(event);
        return;
    }
    // The SDK decides when it captures, so consent given now covers this
    // event only.
    sentry_user_consent_give();
    sentry_capture_event(event);
    sentry_user_consent_revoke();
}

void sentry_set_account(const std::string& account_id)
{
    g_account_id = account_id;
    if (g_started)
        name_person();
}

void sentry_breadcrumb(const char* category, const std::string& message)
{
    if (!g_started)
        return;
    sentry_value_t crumb = sentry_value_new_breadcrumb("default", message.c_str());
    sentry_value_set_by_key(crumb, "category", sentry_value_new_string(category));
    sentry_add_breadcrumb(crumb);
}

} // namespace Slic3r::GUI::JusPrin

#pragma once

// A model provider as data: which API family it speaks, where, how it is
// authenticated, which model it is given by default, what it is called in
// the errors shown to the person, and any fixed headers it wants. The turn
// loop (ProviderAgent) and the codecs read it; the table below is the only
// place a provider's name decides anything.

#include "AgentTransport.hpp"
#include "slic3r/GUI/JusPrin/Updates/Version.hpp"

#include <optional>
#include <stdexcept>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Agent {

// The wire format a provider speaks; one codec per family.
enum class ProviderFamily { Responses, Anthropic };

// How the API key travels: `Authorization: Bearer <key>`, or `x-api-key: <key>`.
enum class AuthStyle { Bearer, ApiKeyHeader };

struct ProviderProfile
{
    std::string    id;
    ProviderFamily family{ProviderFamily::Responses};
    std::string    endpoint;
    AuthStyle      auth{AuthStyle::Bearer};
    // The provider's default; a configured model replaces it in the copy the
    // agent is built with.
    std::string    model;
    // In the error text, as in "The OpenAI API key was rejected".
    std::string    display_name;
    // Sent on every request, after the credential.
    std::vector<AgentHttpHeader> headers;
    // The most output tokens one response may use, for a family that
    // requires the number (Anthropic); 0 where none is sent.
    unsigned       max_tokens{0};
    // How hard the model thinks before a reply, chosen per chat: one of the
    // levels the provider's model list offers for this model ("low",
    // "medium", "high", ...). Empty sends nothing, so the model's own default
    // applies. Title requests never carry it.
    std::string    effort;
    // The credential is a JusPrin account's sign-in rather than an API key,
    // and the endpoint is JusPrin's gateway. Every request names its turn
    // (X-JusPrin-Turn) and says whether it is a title (X-JusPrin-Request),
    // because the gateway charges the account once per turn and never for a
    // title; a refusal means the sign-in has ended, and 402 means the
    // account's allowance is used up. A reply also names its chat
    // (X-JusPrin-Chat), so the gateway can keep the chat whole.
    bool           account_sign_in{false};
    // The provider's own web search, as the Responses API tools list names
    // it: OpenAI's spelling, which JusPrin's gateway passes to OpenAI, unless
    // the row gives its own. The Messages API has one spelling, which
    // AnthropicCodec writes.
    std::string    web_search_type{"web_search"};
};

// Every provider this build can talk to, in the order setup lists them.
inline const std::vector<ProviderProfile>& provider_profiles()
{
    static const std::vector<ProviderProfile> rows{
        // JusPrin's own gateway. Its models are aliases ("slicer-1") that the
        // gateway maps to a provider's model, and each alias says which wire
        // format it is served in; account_profile() turns this row into the
        // one a chat talks to. max_tokens serves the Anthropic format.
        // The server the account signs in to is derived from this endpoint.
        // It is JusPrin's host, not Obico's: the server decides by host which
        // brand's accounts a sign-in uses, and JusPrin's are its own.
        // User-Agent names this JusPrin release to the server.
        {"jusprin", ProviderFamily::Responses, "https://jusprinv2.obico.io/ent/jusprin/v2/responses", AuthStyle::Bearer,
         "slicer-1", "JusPrin", {{"User-Agent", Updates::user_agent()}}, 64000, {}, true},
        {"openai", ProviderFamily::Responses, "https://api.openai.com/v1/responses", AuthStyle::Bearer, "gpt-5.4-mini", "OpenAI", {}, 0},
        // OpenRouter serves the Responses API. The default is the model the
        // OpenAI row uses, so the behaviour is the one already evaluated.
        // X-Title names the app in OpenRouter's usage pages. OpenRouter
        // also reads HTTP-Referer, the app's website, to give it a page of
        // its own; this build has no website constant to send, so it sends
        // none. Its web search is a tool of its own, for any model it serves.
        {"openrouter", ProviderFamily::Responses, "https://openrouter.ai/api/v1/responses", AuthStyle::Bearer,
         "openai/gpt-5.4-mini", "OpenRouter", {{"X-Title", "JusPrin"}}, 0, {}, false, "openrouter:web_search"},
        // The Messages API. max_tokens is required there and also bounds the
        // model's thinking, which this model cannot turn off; 64000 is the
        // value Anthropic suggests for streaming requests.
        {"anthropic", ProviderFamily::Anthropic, "https://api.anthropic.com/v1/messages", AuthStyle::ApiKeyHeader,
         "claude-opus-5-5", "Anthropic", {{"anthropic-version", "2023-06-01"}}, 64000},
    };
    return rows;
}

// The row for a provider id, or null when this build has none.
inline const ProviderProfile* profile_for(const std::string& id)
{
    for (const ProviderProfile& profile : provider_profiles())
        if (profile.id == id)
            return &profile;
    return nullptr;
}

inline const ProviderProfile& openai_profile() { return *profile_for("openai"); }

// The provider a JusPrin account signs in to.
inline const ProviderProfile& account_provider()
{
    for (const ProviderProfile& profile : provider_profiles())
        if (profile.account_sign_in)
            return profile;
    throw std::logic_error("provider_profiles() has no account provider");
}

// The wire formats JusPrin's gateway serves a model in, as its model list
// names them, and the endpoint each one is posted to beside the other.
inline constexpr const char* kFormatAnthropic = "anthropic";
inline constexpr const char* kFormatResponses = "responses";

// The wire format a family speaks, named as the gateway names it. A chat's
// record is kept in one.
inline const char* wire_format(ProviderFamily family)
{
    return family == ProviderFamily::Anthropic ? kFormatAnthropic : kFormatResponses;
}

// Whether a fired skill is shown on the request that fired it only. The
// Messages API can clear it from the turns after (a turn-scoped system
// message, behind a beta header); JusPrin's gateway sends only the headers
// it is configured with, so through it skills stay in place, as they do on
// Responses, which has no such message.
inline bool clears_skills(const ProviderProfile& profile)
{
    return profile.family == ProviderFamily::Anthropic && !profile.account_sign_in;
}

// The beta that turn-scoped system messages need.
inline constexpr const char* kClearAtBeta = "mid-conversation-system-clear-at-2026-08-21";

// An account provider's row as one model is served: the family the format
// names, posted to that format's endpoint next to `endpoint` (the last path
// segment is replaced, so an override or a self-hosted server moves both).
// Null for a format this build does not speak.
inline std::optional<ProviderProfile> account_profile(const ProviderProfile& row, const std::string& endpoint,
                                                      const std::string& format)
{
    ProviderProfile profile = row;
    if (format == kFormatAnthropic)
        profile.family = ProviderFamily::Anthropic;
    else if (format == kFormatResponses)
        profile.family = ProviderFamily::Responses;
    else
        return std::nullopt;
    const std::string base  = endpoint.empty() ? row.endpoint : endpoint;
    const std::size_t slash = base.rfind('/');
    profile.endpoint = (slash == std::string::npos ? base : base.substr(0, slash + 1)) +
                       (format == kFormatAnthropic ? "messages" : "responses");
    return profile;
}

} // namespace Slic3r::GUI::JusPrin::Agent

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

