// OBICO-SERVER-B2N. Anthropic's first reply of a turn holds a web search with
// its result still to come, and a call; its second holds the search's result
// and two more calls. The turn stops while the app is answering those calls.
// The next message's request must still carry the search's result: Anthropic
// refuses a history with a search that has none.
TEST_CASE("a web search whose result came in a reply the turn stopped during keeps its result", "[agent][anthropic][record]")
{
    std::vector<RecordItem> kept;
    auto            transport = std::make_unique<FakeTransport>();
    FakeTransport*  fake      = transport.get();
    AgentServicePtr agent     = make_provider_agent(*profile_for("anthropic"), "key", "", "", std::move(transport), {});

    const auto keep_into = [&kept](AgentRequest& request) {
        request.on_recorded = [&kept](const std::string&, std::vector<RecordItem> items) {
            kept.insert(kept.end(), items.begin(), items.end());
        };
        request.keep_blob = [](const std::string&) -> std::string { return "chats/test/blob"; };
    };
    const auto drain = [&agent]() {
        std::vector<std::string> events;
        for (int i = 0; i < 40; ++i)
            if (auto event = agent->poll())
                events.push_back(describe(*event));
        return events;
    };
    const auto block = [](int index, const json& content, const std::string& input = {}) {
        std::string out = sse(json{{"type", "content_block_start"}, {"index", index}, {"content_block", content}});
        if (!input.empty())
            out += sse(json{{"type", "content_block_delta"}, {"index", index}, {"delta", json{{"type", "input_json_delta"}, {"partial_json", input}}}});
        return out + sse(json{{"type", "content_block_stop"}, {"index", index}});
    };
    const auto reply = [](const std::string& blocks) {
        return sse(json{{"type", "message_start"}, {"message", json{{"id", "msg"}, {"usage", json{{"input_tokens", 100}, {"output_tokens", 1}}}}}}) +
               blocks +
               sse(json{{"type", "message_delta"}, {"delta", json{{"stop_reason", "tool_use"}}}, {"usage", json{{"output_tokens", 10}}}}) +
               sse(json{{"type", "message_stop"}});
    };

    AgentRequest first;
    keep_into(first);
    first.request_id           = "turn-1";
    first.chat_key             = "chat";
    first.record.format        = "anthropic";
    first.session.instructions = "Instructions.";
    first.user_text            = "Find this printer's nozzle size.";
    REQUIRE(agent->start(first));

    // Reply 1: the search, with no result yet, and a call.
    fake->data(reply(block(0, json{{"type", "server_tool_use"}, {"id", "srvtoolu_1"}, {"name", "web_search"}, {"input", json::object()}},
                           R"({"query":"nozzle"})") +
                     block(1, json{{"type", "tool_use"}, {"id", "toolu_1"}, {"name", kTool}, {"input", json::object()}}, "{}")));
    fake->complete();
    CHECK(drain() == std::vector<std::string>{"call toolu_1 workspace_inspect {} await"});
    REQUIRE(agent->continue_after_tool({"toolu_1", "succeeded", R"({"state":"succeeded","result":{}})"}));
    drain();
    REQUIRE(fake->requests.size() == 2);

    // Reply 2: the search's result, then two calls. The turn stops while the
    // first of them is being answered.
    fake->data(reply(block(0, json{{"type", "web_search_tool_result"}, {"tool_use_id", "srvtoolu_1"},
                                   {"content", json::array({json{{"type", "web_search_result"}, {"url", "https://example.test"},
                                                                 {"title", "Nozzle"}, {"encrypted_content", "abc"}}})}}) +
                     block(1, json{{"type", "tool_use"}, {"id", "toolu_2"}, {"name", kTool}, {"input", json::object()}}, "{}") +
                     block(2, json{{"type", "tool_use"}, {"id", "toolu_3"}, {"name", kTool}, {"input", json::object()}}, "{}")));
    fake->complete();
    CHECK(drain() == std::vector<std::string>{"call toolu_2 workspace_inspect {} await"});
    agent->cancel();

    // The next message is built from what was kept.
    AgentRequest next;
    keep_into(next);
    next.request_id           = "turn-2";
    next.chat_key             = "chat";
    next.record.format        = "anthropic";
    next.record.items         = kept;
    next.session.instructions = "Instructions.";
    next.user_text            = "Go on.";
    REQUIRE(agent->start(next));
    const json body = json::parse(fake->requests.back().body);
    INFO(body["messages"].dump(2));

    std::vector<std::string> searches, results;
    for (const json& message : body["messages"])
        if (message["content"].is_array())
            for (const json& content : message["content"]) {
                if (content.value("type", "") == "server_tool_use")
                    searches.push_back(content.value("id", ""));
                if (content.value("type", "") == "web_search_tool_result")
                    results.push_back(content.value("tool_use_id", ""));
            }
    CHECK(searches == std::vector<std::string>{"srvtoolu_1"});
    CHECK(results == searches);
}
