            checked={updates.checkUpdates} onChange={(on) => actions.set('checkUpdates', on)} />
        )}
        <Row title={t`Built-in printer and filament profiles`}
          detail={t`Update with each JusPrin release. Your own presets never change.`} />
      </Group>
